  str_world_boss_leveldesc_hard_7101005 = "- Aurorians สามารถซ้อนเอฟเฟกต์ Assault เมื่อโจมตีมอนสเตอร์ หลังจากถูกโจมตีโดยมอนสเตอร์และ <color=#cc0e0e>การสูญเสีย HP จำนวนสแต็คจะรีเซ็ตเป็นศูนย์</color>.\n- เอฟเฟกต์ Assault สามารถซ้อนทับได้สูงสุด <color=#cc0e0e>150</color> ครั้ง.\n- Astor สร้างความเสียหายเล็กน้อยให้กับ Aurorians ทุกครั้งที่จุด Deathly Candle",
  str_world_boss_bossdesc_7101001 = "Aurorian Element Counter ดาเมจ +100%\nออโรเรียนได้รับแผ่นเสริมประสิทธิภาพ 1 แผ่นสำหรับทุกๆ 3 แผ่นที่พวกเขาย้าย",
  str_world_boss_leveldesc_normal_7101001 = "- ออโรเรียนได้รับแผ่นเสริมประสิทธิภาพ 1 แผ่นสำหรับทุกๆ 3 แผ่นที่พวกเขาย้าย",
  str_world_boss_leveldesc_hard_7101001 = "- ออโรเรียนได้รับแผ่นเสริมประสิทธิภาพ 1 แผ่นสำหรับทุกๆ 3 แผ่นที่พวกเขาย้าย\n- เพิ่ม <color=#cc0e0e>เชนคอมโบดาเมจ</color> ที่มอนสเตอร์ได้รับ 10% ต่อรอบ และลด <color=#cc0e0e>การโจมตีปกติ</color> ความเสียหายที่ได้รับต่อรอบ 10%",
  str_world_boss_bossdesc_7101007 = "Aurorian Element Counter ดาเมจ +100%\nกระเบื้องที่ Aurorians สร้างวัตถุอัญเชิญจะถูกแปลงเป็นกระเบื้องสี",
  str_world_boss_leveldesc_normal_7101007 = "- เมื่อมีการอัญเชิญออโรเรียนใหม่ปรากฏขึ้นบนสนาม ไทล์ด้านล่างจะถูกแปลงเป็นไทล์สี",
  str_world_boss_leveldesc_hard_7101007 = "- เมื่อมีการอัญเชิญออโรเรียนใหม่ปรากฏขึ้นบนสนาม ไทล์ด้านล่างจะถูกแปลงเป็นไทล์สี\n- ออโรเรียน <color=#cc0e0e>ความเสียหายจากสกิลใช้งาน</color> เพิ่มขึ้น 100%\n- เมื่อ <color=#cc0e0e>HP ปัจจุบัน</color> ร่างโคลนของ Augean มีค่ามากกว่า 90% ได้รับประโยชน์จาก DEF ที่เพิ่มขึ้น 100%",
  str_world_boss_bossdesc_7101003 = "Aurorian Element Counter ดาเมจ +100%\nเมื่อมียูนิตที่เรียกโดย Aurorians ในสนามรบ ATK จะเพิ่มขึ้น 10%",
  str_world_boss_leveldesc_normal_7101003 = "- เมื่อมียูนิตที่อัญเชิญโดย Aurorians ในสนามรบ ATK ของผู้อัญเชิญจะเพิ่มขึ้น 10%",
  str_world_boss_leveldesc_hard_7101003 = "- เมื่อมียูนิตที่อัญเชิญโดย Aurorians ในสนามรบ ATK ของผู้อัญเชิญจะเพิ่มขึ้น 10%\n- สัตว์ประหลาดคือ <color=#cc0e0e>มีภูมิคุ้มกันต่อ Active Skill</color> ความเสียหาย. <color=#cc0e0e>เชนคอมโบดาเมจ</color> ถ่ายเพิ่มขึ้น 30% และ <color=#cc0e0e>ความเสียหายจากการโจมตีปกติ</color> ถ่ายลดลง 30%",
  str_world_boss_leveldesc_normal_7101009 = "- เมื่อออโรเรียนสไนเปอร์ใช้คอมโบต่อเนื่อง จะมีการใช้เพิ่มเติม 1 ครั้งที่จุดเริ่มต้น",
  str_world_boss_leveldesc_hard_7101010 = "- เมื่อ Sniper Aurorian ใช้ Chain Combo, มันจะใช้มันเพิ่มเติม 1 ครั้งที่จุดเริ่มต้น\n- Aurorians ทำให้ความเสียหายเพิ่มเติม 50% ต่อ <color=#cc0e0e>ศัตรูที่พวกเขาได้ทำเครื่องหมาย</color>\n- <color=#cc0e0e>DEF ของ Minos เพิ่มขึ้น</color> 10%",
  str_world_boss_bossdesc_7101009 = "ออโรเรียนทำดาเมจชนะทางธาตุ +100%\nเมื่อ Sniper Aurorian ใช้ Chain Combo มันจะใช้เวลาเพิ่มขึ้น 1 ครั้งที่จุดเริ่มต้น",
  str_world_boss_leveldesc_normal_7101112 = "- หาก Active Skill พร้อมใช้งานแล้ว ATK ของ Aurorians จะเพิ่มขึ้น 15% ในรอบนี้",
  str_world_boss_leveldesc_hard_7101112 = "- หาก Active Skill พร้อมใช้งาน, ATK ของ Aurorians จะเพิ่มขึ้น 15% ในรอบนี้\n- เพิ่ม <color=#cc0e0e>จำนวนของ Gloom Ghouls ที่ถูกเรียกมา</color> ถึง 6\n- เพิ่ม <color=#cc0e0e>ความเสียหายจาก Active Skill</color> ของ Aurorians 30% และฟื้นฟู HP ของพวกเขา 10% ของความเสียหายจาก Active Skill",
  str_world_boss_bossdesc_7101112 = "Aurorians' Element Counter ดาเมจ +100%\nNozard มีภูมิคุ้มกันต่อความเสียหายจากการโจมตีปกติ และ Gloom Ghouls มีภูมิคุ้มกันต่อความเสียหายจากทักษะ\nเพิ่ม ATK ของ Aurorians ในรอบนี้หาก Active Skill พร้อม",
  str_world_boss_leveldesc_normal_7101013 = "- เมื่อสกิลใช้งานกำลังเปลี่ยนสีช่อง จะทำความเสียหายต่อศัตรูตามจำนวนช่องสีแดงที่สร้างขึ้น",
  str_world_boss_leveldesc_hard_7101013 = "- เมื่อสกิลใช้งานกำลังเปลี่ยนสีช่อง จะทำดาเมจใส่ศัตรูตามจำนวนช่องสีแดงที่สร้างขึ้น\n- <color=#cc0e0e>DEF ของ Casta เพิ่มขึ้น</color> 20%\n- เมื่อ Casta อยู่<color=#cc0e0e>บนช่องที่ถูกทำลาย</color>, <color=#cc0e0e>DEF ของเธอจะลดลง</color> 75%",
  str_world_boss_leveldesc_normal_7101011 = "- ทุกๆ 3 รอบ รีเซ็ตไทล์ภายใน 1 คลัสเตอร์รอบๆ และสร้างไทล์สีน้ำเงินจำนวนเล็กน้อยที่ขอบแผนที่",
  str_world_boss_leveldesc_hard_7101011 = "- <color=#cc0e0e>ทุก 2 รอบ</color>, รีเซ็ตช่องในวงรอบตัว 1 ชั้น, สร้างช่องสีน้ำเงินบางช่องที่ขอบแผนที่\n- <color=#cc0e0e>เพิ่มความเสียหายของศัตรู</color>, ในขณะที่ <color=#cc0e0e>ผลของการรักษาของ Aurorians เพิ่มขึ้น</color> 80%\n. เมื่อ Aurorians <color=#cc0e0e>รักษาตัวเอง</color>, มัน<color=#cc0e0e>ทำให้ศัตรูได้รับความเสียหายจริง</color> ตามจำนวนการรักษา.",
  str_world_boss_bossdesc_7101013 = "ดาเมจชนะทางธาตุของออโรเรียน +100%.\nเมื่อสกิลใช้งานของออโรเรียนสร้างช่องสีแดง, สร้างความเสียหายให้ศัตรู.",
  str_world_boss_bossdesc_7101011 = "ดาเมจชนะทางธาตุของออโรเรียน +100%.\nSolmorph รีเซ็ตช่องว่างรอบ ๆ และสร้างช่องว่างสีน้ำเงินเพิ่มเติม",
  str_world_boss_bossdesc_7001098 = "ออโรเรียนทำดาเมจชนะทางธาตุ +100%\nสร้างรูนสายฟ้าในแต่ละรอบและเรียกฟ้าผ่าตามมา\nสร้างกระเบื้องปริซึมสีเหลืองในรูปแบบกากบาทหลังจากที่รูนหายไป",
  str_world_boss_leveldesc_normal_70010981 = "- สร้าง Lightning Rune ใต้ Aurorians ในแต่ละรอบและเรียกฟ้าผ่า <color=#cc0e0e>หลังจากการเชื่อมต่อช่องสิ้นสุด</color>\n- <color=#cc0e0e>สร้างกระเบื้องปริซึมสีเหลืองในรูปแบบข้าม</color> หลังจากที่รูนหายไป",
  str_world_boss_leveldesc_hard_70010982 = "- สร้าง Lightning Rune ใต้ Aurorians ในแต่ละรอบและเรียกฟ้าผ่า <color=#cc0e0e>หลังจากการเชื่อมต่อไทล์สิ้นสุด</color>\n- <color=#cc0e0e>สร้าง Prism Tiles สีเหลืองในรูปแบบข้าม</color> หลังจากที่รูนหายไป\n- บอสรับ <color=#cc0e0e>ความเสียหายจากสกิลใช้งานลดลง 50%</color>\n- การโจมตีปกติ <color=#cc0e0e>ทุกครั้งที่โจมตี</color> จะเพิ่มความเสียหายจาก Chain Combo ของ Aurorian 2% ในรอบนี้",
  str_world_boss_leveldesc_normal_7001102 = "- เมื่อใดก็ตามที่ร่ายสกิลใช้งาน<color=#cc0e0e>เปลี่ยนสีช่อง</color> จะเปลี่ยนสีช่องรอบ ๆ เจ้าของร้านให้กลายเป็นธาตุของกัปตัน",
  str_world_boss_leveldesc_hard_7001102 = "- เมื่อใดก็ตามที่ใช้ <color=#cc0e0e>สกิลใช้งานแปลงไทล์</color>, มันจะแปลงไทล์รอบ ๆ บอสเป็นธาตุของกัปตันด้วย\n- <color=#cc0e0e>เมื่อใดก็ตามที่ใช้</color> สกิลใช้งานในแต่ละรอบ, บอสจะรับความเสียหายจากสกิลใช้งานน้อยลง 20%, สูงสุด 5 สแต็ก\n- การโจมตีปกติทุกครั้งจะเพิ่ม <color=#cc0e0e>ความเสียหายจากคอมโบต่อเนื่องของออโรเรียน</color> 4% ในรอบนี้",
  str_world_boss_bossdesc_7001102 = "เพิ่มดาเมจชนะทางธาตุของออโรเรียน 100%\nเมื่อใช้สกิลใช้งานแปลงไทล์ ยังแปลงไทล์รอบ ๆ เจ้าของร้านด้วย",
  str_world_boss_leveldesc_normal_7001104 = "- เมื่อ <color=#cc0e0e>HP ของทีมสูงกว่า 60%</color>, จะเพิ่ม ATK ของ Aurorians ฝ่ายมิตรทั้งหมด 15%.\n- เมื่อเข้าสู่สนามรบ, Arorians จะได้รับความเสียหายเท่ากับ 50% ของ Max HP ของพวกเขา.",
  str_world_boss_leveldesc_hard_7001104 = "- เมื่อ <color=#cc0e0e>HP ของทีมสูงกว่า 75%</color>, <color=#cc0e0e>เพิ่ม ATK ของ Aurorians ทั้งหมดในทีมขึ้น 25%</color>.\n- เมื่อ <color=#cc0e0e>HP ของทีมตกต่ำกว่า 40%</color>, <color=#cc0e0e>ATK ของ Aurorians ทั้งหมดในทีมลดลง 25%</color>.\n- เมื่อเข้าสนาม, พันธมิตรของเราจะได้รับความเสียหายเท่ากับ 50% ของ HP สูงสุดของพวกเขา.\n- <color=#cc0e0e>การรักษาทุกครั้ง</color> ในรอบปัจจุบันได้รับการเพิ่มขึ้น 10%, สูงสุด 20 สแต็ก.",
  str_world_boss_bossdesc_7001104 = "เพิ่มความเสียหายตอบโต้ธาตุ Aurorian 100% HP ของ Aurorian ส่งผลต่อความเสียหายที่ทำได้ เมื่อเข้าสู่สนามรบ ชาวออโรเรียนจะได้รับความเสียหายเท่ากับ 50% ของ HP สูงสุดของพวกเขา",
  str_world_boss_leveldesc_normal_7001105 = "- คันนะปรากฏตัวบนสนามรบเพื่อให้กำลังใจแก่เพื่อน ๆ ขณะที่แปลง 4 ช่องที่อยู่รอบ ๆ เธอเป็น <color=#cc0e0e>ช่องที่ได้รับความเสียหายสีแดง</color>\n- เมื่อออโรเรียนผ่านผ่าน 4 ช่องที่อยู่รอบ ๆ คันนะ, <color=#cc0e0e>จำนวนคอมโบจะเพิ่มขึ้น 10</color> สำหรับแต่ละช่องที่ผ่านไป",
  str_world_boss_leveldesc_hard_7001105 = "- คันนะปรากฏบนสนามรบเพื่อให้กำลังใจเพื่อน ๆ ของเธอ ในขณะที่แปลง 4 ช่องที่อยู่รอบ ๆ เธอเป็น <color=#cc0e0e>ช่องที่ถูกทำลายสีแดง</color>\n- เมื่อออโรเรียนผ่านผ่าน 4 ช่องที่อยู่รอบ ๆ คันนะ <color=#cc0e0e>จำนวนคอมโบเพิ่มขึ้น 10</color> สำหรับแต่ละช่องที่ผ่าน\n- ในรอบที่สี่ ระยะเวลาหยุดของทักษะออโรเรียนทั้งหมดจะลดลง 1\n- จักรพรรดิแห่งความตายครอบครองทักษะ <color=#cc0e0e>End of Fate</color> ที่น่ากลัวอย่างมาก",
  str_world_boss_bossdesc_7001105 = "ออโรเรียนทำดาเมจชนะทางธาตุ +100%\nคันนะปรากฏขึ้นในสนามรบเพื่อให้กำลังใจให้เพื่อน ๆ",
  str_world_boss_leveldesc_normal_7001106 = "- โทรุปรากฏบนสนามรบเพื่อให้กำลังใจแก่เพื่อน ๆ ด้วยการใช้สกิลทุกรอบและทำความเสียหาย 5 ครั้ง ความสามารถนี้ยังจะรีเซ็ตช่องที่ไม่ใช่สีเหลืองภายใน 1 วงรอบที่อยู่รอบ ๆ",
  str_world_boss_leveldesc_hard_7001106 = "- โทรุปรากฏขึ้นในสนามรบเพื่อให้กำลังใจเพื่อน โดยใช้สกิลทุกรอบเพื่อทำความเสียหายทั้งหมด 5 ครั้ง และรีเซ็ตไทล์ที่ไม่ใช่สีเหลืองภายใน 1 วงรอบที่อยู่รอบ ๆ\n- ในรอบที่สี่ ระยะเวลาคูลดาวน์ของสกิล Aurorian ทั้งหมดจะลดลง 1\n- ชูมเมอร์มีความสามารถในการ<color=#cc0e0e>เพิ่มคุณสมบัติของเธออย่างมาก</color>",
  str_world_boss_bossdesc_7001106 = "Aurorian Element Counter ดาเมจ +100%\nโทรุ ปรากฏตัวในสนามรบเพื่อให้กำลังใจแก่เพื่อนๆ",
  str_world_boss_bossdesc_7001110 = "Aurorian Element Counter ดาเมจ +100%\nการโจมตีปกติของออโรเรียนลดสแต็ก Poison ที่ตัวเอง",
  str_world_boss_leveldesc_normal_7001110 = "- <color=#cc0e0e>การใช้สกิลใช้งาน</color> <color=#cc0e0e>สร้าง 2 ช่องเด็กไทล์</color> ภายใน 1 กลุ่มรอบเจ้าของร้าน\n- การโจมตีปกติของออโรเรียนลดจำนวน Poison stacks บนตัวเอง",
  str_world_boss_leveldesc_hard_7001110 = "- <color=#cc0e0e>การใช้ Active Skills</color> <color=#cc0e0e>สร้าง 1 Dark Tile</color> ภายใน 1 วงรอบของเจ้าของร้าน\n- การโจมตีปกติของ Aurorians ลด Poison stacks บนตัวเอง\n- <color=#cc0e0e>ลดความเสียหายที่ได้รับ</color> บน 8 ช่องนอกของเจ้าของร้าน\n- <color=#cc0e0e>การผ่านผ่าน Dark Tile</color> <color=#cc0e0e>เพิ่ม ATK</color> ของ Aurorians ทั้งหมดในทีม",
  str_world_boss_leveldesc_normal_7001111 = "- ออโรเรียนในตำแหน่งกัปตันจะทำดาเมจเพิ่มเติม 1 ครั้ง ด้วยการโจมตีปกติทุกครั้ง",
  str_world_boss_leveldesc_hard_7001111 = "- ออโรเรียนที่อยู่ในตำแหน่งกัปตันทำให้เกิดความเสียหายเพิ่มเติม 1 ครั้งด้วยการโจมตีปกติ\n- ลดความเสียหายที่ศัตรูได้รับจากสกิลใช้งานลง 80%\n- เพิ่มความเสียหายที่ศัตรูได้รับจากการโจมตีปกติขึ้น <color=#cc0e0e>30%</color>",
  str_world_boss_bossdesc_7001111 = "Aurorian Element Counter ดาเมจ +100%\nออโรเรียนในตำแหน่งกัปตันสร้างความเสียหายเพิ่มเติมในการโจมตีปกติ",
  str_world_boss_leveldesc_normal_7001112 = "- สำหรับแต่ละ <color=#cc0e0e>กระเบื้องสีแดง</color> บนสนาม, ความเสียหายสุดท้ายของ Aurorian จะเพิ่มขึ้น <color=#cc0e0e>1%</color>.",
  str_world_boss_leveldesc_hard_7001112 = "- สำหรับแต่ละ <color=#cc0e0e>ไทล์สีแดง</color> บนสนาม, ความเสียหายสุดท้ายของ Aurorian จะเพิ่มขึ้น <color=#cc0e0e>1%</color>.\n- 2 Scroungers จะปรากฏบนสนาม, ซึ่ง Aurorian ไม่สามารถสร้างความเสียหายให้ได้.\n- Scroungers มี <color=#cc0e0e>สกิลตอบโต้</color> และจะเคลื่อนที่หลังจาก Aurorian ปล่อย Active Skill.",
  str_world_boss_bossdesc_7001112 = "Aurorian Element Counter ดาเมจ +100%\nกระเบื้องสีแดงในสนามเพิ่มความเสียหายสำหรับออโรเรียน",
  str_world_boss_leveldesc_normal_7001113 = "- หลังจากที่เอาชนะศัตรู แปลงตำแหน่งของตัวเองเป็น<color=#cc0e0e>ไทล์สี</color>",
  str_world_boss_leveldesc_hard_7001113 = "- หลังจากที่ทำลายศัตรู จะเปลี่ยนตำแหน่งของตัวเองเป็น <color=#cc0e0e>ไทล์สี</color>.\n- ด้วยการโจมตีปกติทุกครั้ง ออโรเรียนสะสมสแต็ก โดยสแต็กแต่ละอันจะเพิ่มความเสียหายจากสกิล Chain Combo ขึ้น <color=#cc0e0e>3%</color>.\n- ลดความเสียหายที่ศัตรูได้รับจากสกิลใช้งานลง <color=#cc0e0e>80%</color>.",
  str_world_boss_bossdesc_7001113 = "Aurorian Element Counter ดาเมจ +100%\nสร้างกระเบื้องสีเมื่อควบคุมศัตรูพืช",
  str_world_boss_leveldesc_normal_7001114 = "- ทักษะการทำความเสียหายในพื้นที่ของ Aurorians สามารถล้างช่องที่มี Poison Mark ได้",
  str_world_boss_leveldesc_hard_7001114 = "- ทักษะทำความเสียหายในพื้นที่ของ Aurorians สามารถใช้เพื่อลบแผ่นที่มาร์คพิษ\n- ในตอนเริ่มต้นการต่อสู้และเมื่อใช้ Butterfly Onslaught, เจ้าของร้านจะเรียกแผ่นที่มาร์คพิษจำนวนมาก\n- ทุกรอบ, 1 <color=#cc0e0e>แผ่นมืด</color> จะปรากฏรอบ ๆ Aurorians.",
  str_world_boss_bossdesc_7001114 = "Aurorian Element Counter ดาเมจ +100%\nแปลง Poison Mark tiles เป็น Dark Tiles เมื่อทำความสะอาด",
  str_world_boss_leveldesc_normal_7001115 = "- เมื่อทุ่งโคลนหายไป ช่องที่มันครอบคลุมจะกลายเป็นสีเดียวกับกัปตัน",
  str_world_boss_leveldesc_hard_7001115 = "- เมื่อทุ่งโคลนหายไป ไทล์ที่มันครอบคลุมจะกลายเป็นสีเดียวกับกัปตัน\n- เมื่อทุ่งโคลนหายไป ไทล์ที่มันครอบคลุมจะถูกเปลี่ยนเป็น <color=#cc0e0e>ไทล์สีดำ</color> โดยอัตโนมัติ\n- เพิ่มความเสียหายจากสกิล Chain Combo ของ Aurorian ที่เป็นกัปตันในขณะนี้ <color=#cc0e0e>50%</color>\n- เจ้าของร้าน <color=#cc0e0e>มีภูมิคุ้มกันต่อการโจมตีปกติของ Aurorians</color>",
  str_world_boss_bossdesc_7001115 = "Aurorian Element Counter ดาเมจ +100%\nเมื่อทุ่งโคลนหายไป กระเบื้องที่มันครอบครองจะกลายเป็นสีเดียวกับกัปตัน",
  str_world_boss_bossdesc_7001119 = "Aurorian Element Counter ดาเมจ +100%\nสร้าง Dark Tile ที่ตำแหน่งของผีเมื่อมันตาย\n5 คอลัมน์ของกระเบื้องที่อยู่ตรงกลางเจ้าของร้านย้ายถอยหลัง 1 แผ่นในทุกรอบ",
  str_world_boss_leveldesc_normal_7001119 = "- ผีสร้าง Dark Tile ที่ตำแหน่งของพวกเขาเมื่อพวกเขาตาย\n- 5 คอลัมน์ของช่องที่อยู่ตรงกลางเจ้าของร้านจะย้อนกลับไป 1 ช่องในทุกรอบ",
  str_world_boss_leveldesc_hard_7001119 = "- ผีสร้าง Dark Tiles ที่ตำแหน่งของพวกเขาเมื่อพวกเขาตายในรอบของ Aurorian\n- 5 คอลัมน์ของกระเบื้องที่อยู่ตรงกลางบอสจะย้อนกลับไป 1 ช่องทุกๆรอบ\n- การผ่านผ่าน Dark Tile จะเพิ่มความเสียหายจาก Active Skill การใช้ Active Skill แต่ละครั้งจะใช้ค่าชาร์จ",
  str_world_boss_eliminate_mode = "โหมดเอนไลต์เทนเมนต์",
  str_world_boss_eliminate = "Codex ความอ้างว้างของการรู้ลึก",
  str_world_boss_eliminate_tip1 = "โหมด Codex ความรกร้างว่างเปล่า",
  str_world_boss_eliminate_tip2 = "โหมดสติปัญญาสำหรับ Codex ความอ้างว้างกลับมาแล้ว!\nในโหมดสติปัญญา, ไม่จำเป็นต้องเชื่อมต่อไทล์; เพียงแค่แตะที่ไทล์เพื่อนำออก\nหลังจากนั้น, ชาวออโรเรียนสามารถสร้างคอมโบลูกโซ่ตามจำนวนไทล์ที่ถูกนำออก.",
  str_world_boss_bossdesc_7001121 = "Aurorian Element Counter ดาเมจ +100%\nกำจัด Salvo Gun และ Dark Tile จะสร้างขึ้นในที่ที่ต้องการ\nเพิ่มดาเมจการโจมตีปกติอย่างถาวรหลังจากผ่าน Dark Tile",
  str_world_boss_bossdesc_7001123 = "เกมจะจบเมื่อสัตว์ Nian ทำลายประตูและเข้าสู่เมือง\nดาเมจชนะทางธาตุของออโรเรียน +100%\nเข้าสู่ช่วงออโรราไทม์ทุกรอบที่สอง\nใช้สกิลที่มีผลทันทีเพื่อขับไล่สัตว์ Nian กลับไป",
  str_world_boss_bossdesc_7001125 = "ดาเมจชนะทางธาตุของออโรเรียน +100%\nหลังจากการโทรพอร์ต ออโรเรียนแปลงแผ่นที่อ่อนแอใกล้เคียงเป็นแผ่นที่เสริมแรง",
  str_world_boss_bossdesc_7001126 = "Aurorian Element Counter ดาเมจ +100%\nได้รับการนับเมื่อ Aurorians ใช้สกิลที่ใช้งานเพื่อทำความเสียหาย, โทรพอร์ต, หรือแปลงกระเบื้อง\nทุก 3 การนับ, คูลดาวน์สกิลที่ใช้งานของ Aurorian ลดลง 1 รอบ\nทุก 3 การนับ, ความเสียหายจะถูกทำให้กับบอส",
